use xiom.io;

use xiom.string;
fn main() {
  let adjective: Str = "awesome";
  let noun: Str = "coder";
  let space: Str = " ";
  let with_space: Str = string.str_concat(adjective, space);
  let phrase: Str = string.str_concat(with_space, noun);
  io.println(phrase);
}
